questions.solution_sql:
SELECT emp_name, salary FROM employees
ORDER BY salary DESC
LIMIT 5;

SELECT * FROM employees
ORDER BY emp_id
LIMIT 4 OFFSET 3;

CREATE TABLE students (
  id INT PRIMARY KEY,
  name VARCHAR(50) NOT NULL,
  marks INT
);

CREATE TABLE enrollments (
  enroll_id INT PRIMARY KEY,
  student_id INT,
  course VARCHAR(50),
  FOREIGN KEY (student_id) REFERENCES students(id)
);

CREATE TABLE users (
  user_id INT PRIMARY KEY AUTO_INCREMENT,
  email VARCHAR(100) UNIQUE,
  age INT CHECK (age >= 18),
  country VARCHAR(30) DEFAULT 'India'
);

START TRANSACTION;
UPDATE employees SET salary = salary * 2;
ROLLBACK;

SELECT dept_id, COUNT(*) AS emp_count
FROM employees
GROUP BY dept_id;

SELECT dept_id, AVG(salary) AS avg_sal
FROM employees
GROUP BY dept_id;

SELECT dept_id, city, COUNT(*) AS cnt
FROM employees
GROUP BY dept_id, city;

SELECT dept_id, MAX(salary) AS top_salary
FROM employees
GROUP BY dept_id;

SELECT customer_id, SUM(amount) AS total_spent
FROM orders
GROUP BY customer_id;

SELECT dept_id, SUM(salary) AS total
FROM employees
GROUP BY dept_id WITH ROLLUP;

SELECT e.emp_name, d.dept_name
FROM employees e
INNER JOIN departments d ON e.dept_id = d.dept_id;

SELECT e.emp_name, d.dept_name
FROM employees e
LEFT JOIN departments d ON e.dept_id = d.dept_id;

SELECT d.dept_name, e.emp_name
FROM departments d
LEFT JOIN employees e ON d.dept_id = e.dept_id;

SELECT e.emp_name AS employee, m.emp_name AS manager
FROM employees e
LEFT JOIN employees m ON e.manager_id = m.emp_id;

SELECT c.cust_name, o.order_id, o.amount
FROM customers c
JOIN orders o ON c.customer_id = o.customer_id;

SELECT e.emp_name, d.dept_name
FROM employees e
CROSS JOIN departments d;

SELECT e.emp_name, d.dept_name FROM employees e LEFT JOIN departments d ON e.dept_id = d.dept_id
UNION
SELECT e.emp_name, d.dept_name FROM employees e RIGHT JOIN departments d ON e.dept_id = d.dept_id;

SELECT DISTINCT m.emp_name
FROM employees e
JOIN employees m ON e.manager_id = m.emp_id;

SELECT emp_name, dept_name
FROM employees
JOIN departments USING (dept_id);

SELECT e.emp_name, e.salary
FROM employees e
WHERE e.salary > (SELECT AVG(salary) FROM employees WHERE dept_id = e.dept_id);

SELECT emp_name, salary,
  (SELECT AVG(salary) FROM employees x WHERE x.dept_id = e.dept_id) AS dept_avg
FROM employees e;

SELECT emp_name, TIMESTAMPDIFF(YEAR, hire_date, CURDATE()) AS years
FROM employees
HAVING years >= 6;

SELECT emp_name,
  CASE WHEN dept_id = 10 THEN salary * 1.10 ELSE salary * 1.05 END AS new_salary
FROM employees;

SELECT city FROM employees
UNION
SELECT city FROM customers;

SELECT city FROM employees
UNION ALL
SELECT city FROM customers;

SELECT emp_name, salary,
  RANK() OVER (ORDER BY salary DESC) AS rnk
FROM employees;

SELECT emp_name, salary,
  DENSE_RANK() OVER (ORDER BY salary DESC) AS drnk
FROM employees;

SELECT emp_name, salary,
  ROW_NUMBER() OVER (ORDER BY salary DESC) AS rn
FROM employees;

SELECT emp_name, dept_id, salary,
  RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS dept_rank
FROM employees;

SELECT DISTINCT salary FROM (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r FROM employees) t
WHERE r = 3;

SELECT emp_name, hire_date, salary,
  LAG(salary) OVER (ORDER BY hire_date) AS prev_salary
FROM employees;

SELECT order_date, amount,
  SUM(amount) OVER (ORDER BY order_date, order_id) AS running_total
FROM orders;

SELECT emp_name, dept_id, salary,
  AVG(salary) OVER (PARTITION BY dept_id) AS dept_avg
FROM employees;

WITH avg_cte AS (
  SELECT AVG(salary) AS avg_sal FROM employees
)
SELECT e.emp_name, e.salary
FROM employees e, avg_cte
WHERE e.salary > avg_cte.avg_sal;

SELECT DISTINCT salary FROM employees
ORDER BY salary DESC
LIMIT 1 OFFSET 4;

DELETE e1 FROM employees e1
JOIN employees e2
  ON e1.emp_name = e2.emp_name AND e1.city = e2.city AND e1.emp_id > e2.emp_id;

SELECT DISTINCT e1.emp_name, e1.hire_date
FROM employees e1
JOIN employees e2 ON e1.hire_date = e2.hire_date AND e1.emp_id <> e2.emp_id;

(SELECT * FROM employees ORDER BY emp_id ASC LIMIT 1)
UNION ALL
(SELECT * FROM employees ORDER BY emp_id DESC LIMIT 1);

SELECT * FROM (
  SELECT * FROM employees ORDER BY emp_id DESC LIMIT 3) t
ORDER BY emp_id;

SELECT * FROM employees
WHERE salary IN (
  SELECT salary FROM employees GROUP BY salary HAVING COUNT(*) > 1);

SELECT yr, cnt, SUM(cnt) OVER (ORDER BY yr) AS cumulative
FROM (
  SELECT YEAR(hire_date) AS yr, COUNT(*) AS cnt FROM employees GROUP BY YEAR(hire_date)) t;

SELECT dept_id FROM employees
GROUP BY dept_id
HAVING MIN(salary) > 30000;
